INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT122-S1-Q15$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$Either the sculpture isn't art, or not all art evokes intense feelings.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$If all art evokes feelings and this is art, it evokes feelings. It doesn't.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$Recipe: (All A are B, and x is A) → x is B. x isn't B. So either not all A are B, or x isn't A. Denying the result knocks out at least one of the two premises.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Same conditional, the result denied, and an "or" conclusion naming both premises.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT122-S1-Q15$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
